def options(texts, key):
    indices = list(range(len(texts)))
    random.Random(f'{SEED}:{key}').shuffle(indices)
    values = [{'id':f'o{n+1}','text':texts[index]} for n,index in enumerate(indices)]
    targets = {index:values[n]['id'] for n,index in enumerate(indices)}
    return values, targets


def case(situation, texts, key, target=0, **extra):
    values, ids = options(texts,key)
    return {'situation':situation,'options':values,'target':ids[target],**extra}


def write_item(item):
    from .validate import protected_names
    text='\n'.join(m['text'] for s in item['teaching'] for m in s['messages'])
    item['protected_names']=protected_names(text)
    path = HERE/'candidates'/f"{item['id']}.json"
    path.parent.mkdir(exist_ok=True)
    if path.exists(): raise ValueError('candidate_exists')
    path.write_text(json.dumps(item,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')


def author_p():
    rows = [r.split('|') for r in P_TEXT.strip().splitlines()][:48]
    for n,row in enumerate(rows,1):
        if len(row)!=13: raise ValueError((n,len(row)))
        pref,domain,choice,reply,incidental,s1,t1,d1,o1,s2,t2,d2,o2=row
        item_id=f'P{n:02}'
        first=1+(n-1)%3; second=first+3
        tests=[case(s1,[t1,d1,o1,'把话题转向天气。','先确认你此刻想要哪一种。'],item_id+':T1',phase='T1',domain=domain),
               case(s2,[t2,d2,o2,'把话题转向天气。','先确认你此刻想要哪一种。'],item_id+':T2',phase='T2',domain='跨领域迁移')]
        item={'id':item_id,'category':'P','preference':pref,'teaching_domain':domain,
              'teaching':[{'dialogue':first,'mode':'choice','messages':[{'speaker':'assistant','text':choice},{'speaker':'user','text':reply}]},
                          {'dialogue':second,'mode':'incidental','messages':[{'speaker':'user','text':incidental}]}],
              'tests':tests,'ceiling':pref,'counterintuitive':f'常见默认是“{d1}”；此人的两次选择暗示不同取向。',
              'protected_names':[]}
        write_item(item)


if __name__ == '__main__':
    author_p()
